    // as de outro período ou matéria são ignoradas aqui. siglaDoCurso é o curso atual do
    // aluno, para item restrito a curso.
    public static ResultadoDaConcessao Conceder(
        ItemMedalha item,
        int versaoDoItem,
        Usuario aluno,
        string siglaDoCurso,
        Turma turma,
        SemestreLetivo semestreDaTurma,
        Usuario professor,
        IEnumerable<Medalha> existentes,
        DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(item);
        ArgumentNullException.ThrowIfNull(aluno);
        ArgumentNullException.ThrowIfNull(turma);
        ArgumentNullException.ThrowIfNull(semestreDaTurma);
        ArgumentNullException.ThrowIfNull(professor);
        ArgumentNullException.ThrowIfNull(existentes);

        if (semestreDaTurma.Id != turma.SemestreLetivoId)
        {
            throw new ArgumentException("O semestre não é o da turma.", nameof(semestreDaTurma));
    // cursoDoAluno: o curso atual, para o evento e o item restritos a curso. materia: só na
    // apresentação em sala; que o aluno estuda a matéria é pergunta ao banco, feita antes
    // por quem chama. ultimoEncerrado: o semestre letivo de fim mais recente antes de hoje.
    public static ResultadoDaReivindicacao Reivindicar(
        ItemPremioParticipacao item,
        int versaoDoItem,
        Usuario aluno,
        Curso? cursoDoAluno,
        Evento evento,
        Materia? materia,
        SemestreLetivo? ultimoEncerrado,
        DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(item);
        ArgumentNullException.ThrowIfNull(aluno);
        ArgumentNullException.ThrowIfNull(evento);

        if (aluno.Papeis != Papeis.Aluno)
        {
            throw new DomainException($"Só aluno reivindica prêmio de participação; {aluno.Id} é {aluno.Papeis}.");
        }
            fila.Enfileirar(new AvaliarFechamentoDoAluno(carga.TipoDePeriodo, carga.ReferenciaDoPeriodo, aluno));
        }

        await unitOfWork.SalvarAsync(cancellationToken);
    }
}

