using Maxx.Application.Autenticacao;
using Maxx.Application.Conquistas;
using Maxx.Application.Fila;
using Maxx.Application.Posts;
using Maxx.Application.Ranking;
using Maxx.Domain.Academico;

namespace Maxx.Application.Medalhas;

// Anulação de medalha pela instituição (produto.md 4.8): ato administrativo, sem motivo
// público e sem averiguação. Na fase 1, por comando administrativo, até a área web do
// passo 12. Grava quem anulou e quando e enfileira o recálculo das conquistas que a medalha
// compunha e os de ranking e raridade, na mesma transação. O post da
// medalha perde o vínculo e fica como post comum; o que era só a medalha é apagado, porque
// post vazio não existe (decisão do passo 7).
public sealed class AnularMedalhaHandler(
    IUsuarioRepository usuarios,
    IMedalhaRepository medalhas,
    IPostRepository posts,
    IFilaDeTrabalhos fila,
    IUnitOfWork unitOfWork,
    TimeProvider relogio)
{
    // false: a medalha já estava anulada, e nada mudou.
    public async Task<bool> AnularAsync(Guid medalhaId, string emailDaInstituicao, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(emailDaInstituicao);

        var instituicao = await usuarios.BuscarPorEmailAsync(emailDaInstituicao.Trim(), cancellationToken);
        if (instituicao is null || !instituicao.Papeis.HasFlag(Papeis.Instituicao))
        {
            throw new RecusaException(
                TipoDeRecusa.Proibido, CodigosDaMedalha.SemContaDeInstituicao, "O e-mail não é de uma conta da instituição.");
        }

        try
        {
            return await TentarAsync(medalhaId, instituicao.Id, cancellationToken);
        }
        catch (ConflitoDeConcorrenciaException)
        {
            // Outra anulação da mesma medalha gravou primeiro. Relida, ela já está anulada.
            unitOfWork.Descartar();
            return await TentarAsync(medalhaId, instituicao.Id, cancellationToken);
        }
    }

    private async Task<bool> TentarAsync(Guid medalhaId, Guid instituicaoId, CancellationToken cancellationToken)
    {
        var medalha = await medalhas.BuscarAsync(medalhaId, cancellationToken)
            ?? throw new RecusaException(
                TipoDeRecusa.NaoEncontrado, CodigosDaMedalha.MedalhaNaoEncontrada, $"Medalha {medalhaId} não existe.");

        if (!medalha.Anular(instituicaoId, relogio.GetUtcNow()))
        {
            return false;
        }

        // O removido pela instituição fica como está: some para todos de qualquer jeito, e
        // apagá-lo perderia quem removeu e quando.
        foreach (var post in await posts.DoPremioAsync(medalha.Id, cancellationToken))
        {
            if (post.EstaRemovido)
            {
                continue;
            }

            if (post.FicariaVazioSemPremio)
            {
                posts.Apagar(post);
            }
            else
            {
                post.DesvincularPremio();
            }
        }

        fila.Enfileirar(new RecalcularConquistasDaMedalha(medalha.Id));
        fila.PedirRecalculos();
        await unitOfWork.SalvarAsync(cancellationToken);
        return true;
    }
}
namespace Maxx.Application;

// Um pedido que a aplicação recusa por regra, não por falha: a borda traduz o tipo em
// status HTTP e devolve o código no formato único de erro. A mensagem é só para o log.
public sealed class RecusaException : Exception
{
    public RecusaException()
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message) : base(message)
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message, Exception innerException) : base(message, innerException)
    {
        Codigo = string.Empty;
    }

    public RecusaException(TipoDeRecusa tipo, string codigo, string? motivoParaLog = null)
        : base(motivoParaLog ?? codigo)
    {
        Tipo = tipo;
        Codigo = codigo;
    }

    public TipoDeRecusa Tipo { get; }

    // Estável e em kebab-case: é o que o cliente usa para escolher a mensagem amigável.
    public string Codigo { get; }
}

public enum TipoDeRecusa
{
    Invalido,
    NaoEncontrado,
    Conflito,
    NaoAutorizado,

    // Autenticado, mas sem direito sobre o recurso: o escopo de turma do professor.
    Proibido,
}

// Gravação recusada por uma unicidade do banco: a corrida que a checagem prévia não
// consegue fechar sozinha.
public sealed class ConflitoDeUnicidadeException : Exception
{
    public ConflitoDeUnicidadeException()
    {
    }

    public ConflitoDeUnicidadeException(string message) : base(message)
    {
    }

    public ConflitoDeUnicidadeException(string message, Exception innerException) : base(message, innerException)
    {
    }

    public ConflitoDeUnicidadeException(Unicidade unicidade, Exception innerException)
        : base($"Unicidade violada: {unicidade}.", innerException)
    {
        Unicidade = unicidade;
    }

    public Unicidade Unicidade { get; }
}

public enum Unicidade
{
    Outra,
    ContaPorCadastro,
    Prefixo,

    // Duas medalhas ativas com a mesma chave de deduplicação: a mesma vaga do período.
    MedalhaAtiva,

    // Duas reivindicações com a mesma chave de deduplicação: um prêmio por evento.
    PremioParticipacaoAtivo,

    // Duas contestações do mesmo prêmio ao mesmo tempo: uma por prêmio.
    ContestacaoPorPremio,

    // Dois posts não removidos para o mesmo prêmio: um prêmio rende um post.
    PostPorPremio,

    // A mesma pessoa curtindo o mesmo post duas vezes ao mesmo tempo.
    Curtida,

    // A mesma conquista concedida duas vezes na mesma instância do período. A trava por
    // aluno no worker evita; o índice é a rede de segurança.
    ConquistaAtiva,

    // O mesmo seguimento gravado duas vezes ao mesmo tempo.
    Seguimento,
}

// Gravação recusada porque a linha mudou desde a leitura (xmin): outro pedido chegou
// antes. Quem chama decide se relê e tenta de novo.
public sealed class ConflitoDeConcorrenciaException : Exception
{
    public ConflitoDeConcorrenciaException()
    {
    }

