            aluno.Conta is { } conta
                ? new ContaDoAlunoResponse(
                    conta.Id, conta.NomeDeExibicao, conta.Arroba, conta.ExAlunoDesde, PostEndpoints.Leitura(armazenamento, conta.ChaveDaFoto))
                : null);
