private static RecusaDaReivindicacao? Validar(
    ItemPremioParticipacao item,
    Usuario aluno,
    Curso? cursoDoAluno,
    Evento evento,
    Materia? materia,
    SemestreLetivo? ultimoEncerrado,
    DateTimeOffset agora,
    Guid donoDoEventoDigitado)
{
