    if (item.Vigencia is { Inicio: { } inicio } && evento.Inicio < inicio || item.Vigencia is { Fim: { } fim } && evento.Inicio > fim)
    {
        return RecusaDaReivindicacao.ItemForaDeVigencia;
    }

