29	
30	        alunos.MapPut("/{cadastroId:guid}/email", CorrigirEmailAsync)
31	            .WithName("CorrigirEmailDoAluno")
32	            .ProducesValidationProblem()
33	            .ProducesProblem(StatusCodes.Status403Forbidden)
34	            .ProducesProblem(StatusCodes.Status404NotFound)
35	            .ProducesProblem(StatusCodes.Status409Conflict);
36	
37	        alunos.MapPost("/{cadastroId:guid}/ex-aluno", MarcarExAlunoAsync)
38	            .WithName("MarcarExAluno")
39	            .ProducesProblem(StatusCodes.Status403Forbidden)
