        Assert.Equal(5, contas.Count);
        Assert.All(contas, conta => Assert.False(conta.TemSenha));
        Assert.Equal(4, contas.Count(conta => conta.Papeis == Papeis.Professor && conta.Sufixo == Sufixo.Professor));
