// Gera o data/demo/mundo.json do passo 12 a partir do atual: 150 alunos (120 ativos, 30
// ex-alunos), dois professores por curso, seis matérias por curso com turma em 2026/1 e
// 2026/2. Determinístico: a mesma saída a cada execução.
const fs = require("fs");
const caminho = process.argv[2];
const mundo = JSON.parse(fs.readFileSync(caminho, "utf8"));
const DOMINIO = "al.unieduk.invalid";

const novasMaterias = {
  CC: ["Redes de Computadores", "Sistemas Operacionais"],
  ADM: ["Finanças Corporativas", "Logística Empresarial"],
  MED: ["Farmacologia", "Semiologia"],
  IA: ["Estatística para Ciência de Dados", "Aprendizado de Máquina"],
};
const segundosProfessores = {
  CC: ["fernando.prado@prof.unieduk.com.br", "Fernando Prado"],
  ADM: ["patricia.lacerda@prof.unieduk.com.br", "Patrícia Lacerda"],
  MED: ["ricardo.tavares@prof.unieduk.com.br", "Ricardo Tavares"],
  IA: ["vanessa.queiroz@prof.unieduk.com.br", "Vanessa Queiroz"],
};
// Ativos e ex-alunos por curso: 30 + 8, 30 + 8, 30 + 7, 30 + 7 = 150.
const exAlunos = { CC: 8, ADM: 8, MED: 7, IA: 7 };

const nomes = [
  "Alice", "Arthur", "Bianca", "Caio", "Carolina", "Daniel", "Eduarda", "Enzo", "Fernanda", "Gabriela",
  "Heitor", "Igor", "Jéssica", "João", "Júlia", "Kaique", "Laura", "Leonardo", "Lívia", "Luana",
  "Manuela", "Matheus", "Melissa", "Murilo", "Natália", "Nicolas", "Olívia", "Otávio", "Paula", "Renan",
  "Rebeca", "Samuel", "Sabrina", "Tatiane", "Vitor", "Yasmin", "André", "Clara", "Davi", "Elisa",
];
const sobrenomes = [
  "Andrade", "Batista", "Campos", "Dias", "Esteves", "Farias", "Guimarães", "Honorato", "Jardim", "Lopes",
  "Macedo", "Nascimento", "Pacheco", "Queiroga", "Ramos", "Siqueira", "Toledo", "Valente", "Xavier", "Zanetti",
  "Bueno", "Coelho", "Domingues", "Freitas", "Garcia", "Leal", "Medeiros", "Neves", "Pinto", "Rezende",
];

const semAcento = (texto) => texto.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
const usados = new Set();
for (const curso of mundo.cursos) {
  for (const aluno of curso.alunos) {
    usados.add(aluno.nomeCompleto);
  }
}

let indice = 0;
function proximoNome() {
  for (;;) {
    const nome = nomes[indice % nomes.length];
    const sobrenome = sobrenomes[Math.floor(indice / nomes.length) * 7 % sobrenomes.length + (indice % 3)] ?? sobrenomes[indice % sobrenomes.length];
    indice++;
    const completo = `${nome} ${sobrenome}`;
    if (!usados.has(completo)) {
      usados.add(completo);
      return completo;
    }
  }
}

for (const curso of mundo.cursos) {
  const sigla = curso.sigla;
  const duracao = curso.duracaoEmSemestres;
  const antigas = curso.materias.map((materia) => materia.nome);
  curso.materias = [...antigas, ...novasMaterias[sigla]].map((nome) => ({ nome, turmas: ["2026/1", "2026/2"] }));
  curso.professores[0].materias = antigas;
