cd "/c/Users/Guilherme Gimenes/Documents/Repos/tcc/maxx-engenheiro/apps/api/tests/Maxx.Api.IntegrationTests" && perl -0pi -e 's/    public async Task Professores_e_instituicao_ganham_conta_sem_senha_e_aluno_nenhum\(\)
.*?
