// Busca candidatas no Wikimedia Commons: só domínio público e CC0, grandes o bastante para a
// derivada de 1080, em temas da vida acadêmica sem pessoas. Grava miniaturas e um JSON com a
// procedência de cada uma, para revisão.
const fs = require("fs");
const path = require("path");
const destino = process.argv[2];
fs.mkdirSync(destino, { recursive: true });

const temas = [
  "library bookshelves interior",
  "open book on desk",
  "laptop programming code screen",
  "empty lecture hall",
  "chemistry laboratory glassware",
  "microscope laboratory",
  "stethoscope",
  "anatomical skeleton model",
  "university campus building",
  "coffee cup and books",
  "whiteboard mathematics",
  "arduino electronics",
  "printed circuit board",
  "trophy cup",
  "auditorium stage empty",
  "graduation cap mortarboard",
  "warehouse shelves logistics",
  "server room data center",
  "3D printer printing",
  "chalkboard equations",
  "notebook and pen",
  "calculator and documents",
  "sports track stadium",
  "donation boxes",
];

const licencas = /^(cc0|public domain|pd)/i;
const agente = "MaxxTCC/1.0 (projeto academico; contato gdfgimenes@gmail.com)";

async function json(url) {
  const resposta = await fetch(url, { headers: { "User-Agent": agente } });
  if (!resposta.ok) throw new Error(`${resposta.status} ${url}`);
  return resposta.json();
}

function limpar(html) {
  return (html ?? "").replace(/<[^>]*>/g, "").replace(/\s+/g, " ").trim();
}

(async () => {
  const candidatas = [];
  for (const tema of temas) {
    const url =
      "https://commons.wikimedia.org/w/api.php?action=query&format=json&generator=search&gsrnamespace=6&gsrlimit=30" +
      `&gsrsearch=${encodeURIComponent(`filetype:bitmap ${tema}`)}` +
      "&prop=imageinfo&iiprop=url|size|extmetadata|mime&iiurlwidth=1280";
    let dados;
    try {
      dados = await json(url);
    } catch (erro) {
      console.error(tema, erro.message);
      continue;
    }
    const paginas = Object.values(dados.query?.pages ?? {});
    let deste = 0;
    for (const pagina of paginas) {
      const info = pagina.imageinfo?.[0];
      const meta = info?.extmetadata ?? {};
      const licenca = limpar(meta.LicenseShortName?.value);
      if (!info || !licencas.test(licenca) || info.mime !== "image/jpeg") continue;
      if (Math.min(info.width, info.height) < 1080) continue;
      const nome = `${String(candidatas.length).padStart(3, "0")}.jpg`;
      const miniatura = info.thumburl.replace(/\/\d+px-/, "/400px-");
      const resposta = await fetch(miniatura, { headers: { "User-Agent": agente } });
      if (!resposta.ok) continue;
      fs.writeFileSync(path.join(destino, nome), Buffer.from(await resposta.arrayBuffer()));
      candidatas.push({
        arquivo: nome,
        tema,
        titulo: pagina.title,
        autor: limpar(meta.Artist?.value) || "Desconhecido",
        licenca,
        pagina: info.descriptionurl,
        grande: info.thumburl,
      });
      if (++deste === 4) break;
    }
    console.log(tema, deste);
  }
  fs.writeFileSync(path.join(destino, "candidatas.json"), JSON.stringify(candidatas, null, 2));
  console.log("total", candidatas.length);
})();

