25	// Determinístico: a mesma semente e a mesma ordem (alunos pelo RA, itens pelo código) geram os
26	// mesmos fatos a cada banco novo, dada a mesma data de corte.
27	public sealed partial class DatabaseSeeder
28	{
29	    // Fatos até a véspera, e nunca depois de 06/11/2026: o mundo foi desenhado até ali.
30	    private static readonly DateOnly _ultimoDiaDosFatos = new(2026, 11, 6);
31	
32	    private sealed class GeradorDeAtividade(
33	        MaxxDbContext db,
34	        IFilaDeTrabalhos fila,
35	        MundoDaAtividade mundo,
36	        DateTimeOffset agora)
37	    {
38	        private readonly Random _sorte = new(20262);
39	        private readonly DateOnly _corte = Min(_ultimoDiaDosFatos, FusoHorario.DataLocal(agora).AddDays(-1));
40	        private readonly Dictionary<(Guid Aluno, string Item), List<Medalha>> _medalhas = [];
41	        private readonly HashSet<string> _chavesDePremio = new(StringComparer.Ordinal);
42	        private readonly Dictionary<Guid, double> _empenho = [];
43	
44	        public int Medalhas { get; private set; }
45	
46	        public int Premios { get; private set; }
47	
48	        public int Avisos { get; private set; }
49	
50	        public void Gerar(AtividadeDemo atividade)
51	        {
52	            foreach (var aluno in mundo.Alunos)
53	            {
54	                // Empenho de 0,15 a 1, concentrado embaixo: poucos alunos ganham muito.
55	                _empenho[aluno.Conta.Id] = 0.15 + (0.85 * Math.Pow(_sorte.NextDouble(), 2));
56	            }
57	
58	            if (atividade.Contestacao is { } contestacao)
59	            {
60	                Contestacao(contestacao);
61	            }
62	
63	            foreach (var (codigo, alunos) in atividade.Medalhas.OrderBy(par => par.Key, StringComparer.Ordinal))
64	            {
65	                MedalhasDoItem(codigo, alunos);
66	            }
67	
68	            foreach (var (codigo, alunos) in atividade.PremiosParticipacao.OrderBy(par => par.Key, StringComparer.Ordinal))
69	            {
70	                PremiosDoItem(codigo, alunos);
71	            }
72	
73	            foreach (var aviso in atividade.Avisos)
74	            {
75	                Publicar(aviso);
76	            }
77	
78	            PedirConquistas();
79	        }
80	
81	        private void MedalhasDoItem(string codigo, int alunos)
82	        {
83	            if (!mundo.ItensDeMedalha.TryGetValue(codigo, out var doCatalogo))
84	            {
85	                throw Erro($"{codigo} não é medalha do catálogo.");
86	            }
87	
