import type { components } from "@maxx/api-client";
import {
  useInfiniteQuery,
  useMutation,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";

import { useApiClient } from "../api/ApiClientProvider";
import { FalhaDaApi } from "../api/FalhaDaApi";

export type ComprovacaoNaFila =
  components["schemas"]["ComprovacaoNaFilaResponse"];
export type EventoNaFila = components["schemas"]["EventoNaFilaResponse"];

// A fila de comprovações (produto.md 4.7): das mais antigas para as mais novas, 20 por
// página, só com os alunos do professor no semestre vigente, conferido pela API. Com o
// evento, só as dele.
export function useFilaDeComprovacoes(eventoId: string | null) {
  const client = useApiClient();

  return useInfiniteQuery({
    queryKey: ["comprovacoes", eventoId],
    initialPageParam: null as string | null,
    queryFn: async ({ pageParam }) => {
      const { data, error } = await client.GET("/api/v1/comprovacoes", {
        params: {
          query: {
            ...(eventoId ? { eventoId } : {}),
            ...(pageParam ? { cursor: pageParam } : {}),
          },
        },
      });
      if (!data) {
        throw FalhaDaApi.doCorpo(error);
      }
      return data;
    },
    getNextPageParam: (pagina) => pagina.proximo ?? null,
  });
}

// Os eventos com comprovação pendente, para os chips do filtro.
export function useEventosDaFila() {
  const client = useApiClient();

  return useQuery({
    queryKey: ["comprovacoes", "eventos"],
    queryFn: async () => {
      const { data, error } = await client.GET("/api/v1/comprovacoes/eventos");
      if (!data) {
        throw FalhaDaApi.doCorpo(error);
      }
      return data;
    },
  });
}

// Decidida (ou decidida por outra pessoa), a comprovação sai da fila: a fila e os chips
// são relidos. O feed também, porque a marca do post muda.
function useAtualizarFila() {
  const queryClient = useQueryClient();
  return () =>
    Promise.all([
      queryClient.invalidateQueries({ queryKey: ["comprovacoes"] }),
      queryClient.invalidateQueries({ queryKey: ["feed"] }),
    ]);
}

export function useAprovar() {
  const client = useApiClient();
  const atualizar = useAtualizarFila();

  return useMutation({
    mutationFn: async (comprovacaoId: string) => {
      const { error, response } = await client.POST(
        "/api/v1/comprovacoes/{comprovacaoId}/aprovacao",
        { params: { path: { comprovacaoId } } },
      );
      if (!response.ok) {
        throw FalhaDaApi.doCorpo(error);
      }
    },
    onSettled: atualizar,
  });
}

export function useReprovar() {
  const client = useApiClient();
  const atualizar = useAtualizarFila();

  return useMutation({
    mutationFn: async ({
      comprovacaoId,
      motivo,
    }: {
      comprovacaoId: string;
      motivo: string;
    }) => {
      const { error, response } = await client.POST(
        "/api/v1/comprovacoes/{comprovacaoId}/reprovacao",
        { params: { path: { comprovacaoId } }, body: { motivo } },
      );
      if (!response.ok) {
        throw FalhaDaApi.doCorpo(error);
      }
    },
    onSettled: atualizar,
  });
}

// Contestação do professor (produto.md 4.7), a partir do "..." do post. O post relido perde
// os pontos e o tier para quem não é o aluno nem a instituição.
export function useContestar() {
  const client = useApiClient();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      premioId,
      motivo,
    }: {
      premioId: string;
      motivo: string;
    }) => {
      const { error, response } = await client.POST(
        "/api/v1/premios-participacao/{premioId}/contestacao",
        { params: { path: { premioId } }, body: { motivo } },
      );
      if (!response.ok) {
        throw FalhaDaApi.doCorpo(error);
      }
    },
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: ["feed"] }),
        queryClient.invalidateQueries({ queryKey: ["post"] }),
        queryClient.invalidateQueries({ queryKey: ["perfil"] }),
      ]),
  });
}
import { useState } from "react";
import { Modal, Pressable, StyleSheet, Text, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { falhaParaTela } from "../api/FalhaDaApi";
import { Button } from "../components/Button";
import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { espacamento } from "../theme/tokens";
import { useContestar } from "./api";
import { FolhaDeMotivo } from "./FolhaDeMotivo";

interface MenuDeContestacaoProps {
  premioId: string;
  nomeDoAluno: string;
  aberto: boolean;
  onFechar: () => void;
}

// O "..." do post para o professor, sobre um prêmio de participação válido (produto.md 4.7,
// D8): contestar, sempre com motivo, dentro dos 15 dias da aprovação. O escopo de turma e a
// janela são conferidos pela API; a recusa aparece dentro da folha. Contestado, o prêmio vai
// a averiguação, e o post relido some com ele para quem não é o aluno nem a instituição.
export function MenuDeContestacao({
  premioId,
  nomeDoAluno,
  aberto,
  onFechar,
}: MenuDeContestacaoProps) {
  const { colors } = useTheme();
  const insets = useSafeAreaInsets();
  const contestar = useContestar();
  const [escrevendo, setEscrevendo] = useState(false);

  const fechar = () => {
    setEscrevendo(false);
    contestar.reset();
    onFechar();
  };

  return (
    <>
      <Modal
        visible={aberto && !escrevendo}
        transparent
        animationType="slide"
        onRequestClose={fechar}
      >
        <View style={styles.fundo}>
          <Pressable
            accessibilityLabel="Fechar"
            style={[StyleSheet.absoluteFill, { backgroundColor: colors.scrim }]}
            onPress={fechar}
          />
          <View
            role="dialog"
            aria-modal
            accessibilityLabel="Opções do post"
            style={[
              styles.folha,
              {
                backgroundColor: colors.bg,
                paddingBottom:
                  espacamento.respiroAntesDaNavegacao + insets.bottom,
              },
            ]}
          >
            <Text style={[textStyles.corpo, { color: colors.ink2 }]}>
              Contestar leva o prêmio para averiguação, e ele para de pontuar
              até a instituição decidir.
            </Text>
            <Button
              label="Contestar prêmio"
              variant="secondary"
              onPress={() => setEscrevendo(true)}
            />
            <Button label="Cancelar" variant="secondary" onPress={fechar} />
          </View>
        </View>
      </Modal>
      <FolhaDeMotivo
        aberta={aberto && escrevendo}
        titulo="Contestar prêmio"
        explicacao={`A instituição decide. ${nomeDoAluno} vê que o prêmio está em averiguação.`}
        confirmar="Contestar"
        enviando={contestar.isPending}
        erro={
          contestar.isError ? falhaParaTela(contestar.error).mensagem : null
        }
        onConfirmar={(motivo) =>
          contestar.mutate({ premioId, motivo }, { onSuccess: fechar })
        }
        onFechar={fechar}
      />
    </>
  );
}

const styles = StyleSheet.create({
  fundo: { flex: 1, justifyContent: "flex-end" },
  folha: {
    borderTopLeftRadius: 16,
    borderTopRightRadius: 16,
    paddingTop: 24,
    paddingHorizontal: espacamento.margemLateral,
    gap: 12,
  },
});
import { ComprovacoesScreen } from "../../comprovacoes/ComprovacoesScreen";

export default ComprovacoesScreen;
import { Redirect, Stack, usePathname, type Href } from "expo-router";

import { Screen } from "../../components/Screen";
import { ErrorState } from "../../components/StateMessage";
import { loginVoltandoPara } from "../../navegacao/voltar";
import { EsperaDaSessao } from "../../sessao/EsperaDaSessao";
import { useSessao } from "../../sessao/SessaoProvider";
import { useTheme } from "../../theme/ThemeProvider";

// Tudo que exige login. Sem sessão, vai para o login, que depois volta para cá (o deep link
// /post/:id); sem conexão para saber, explica e oferece tentar de novo, sem apagar a sessão
// guardada.
export default function AppLayout() {
  const { estado, tentarDeNovo } = useSessao();
  const { colors } = useTheme();
  const caminho = usePathname();

  if (estado === "restaurando") {
    return <EsperaDaSessao />;
  }

  if (estado === "anonimo") {
    return <Redirect href={loginVoltandoPara(caminho) as Href} />;
  }

  if (estado === "sem-conexao") {
    return (
      <Screen>
        <ErrorState
          title="Sem conexão."
          message="Confira a internet e tente de novo."
          onRetry={() => void tentarDeNovo()}
        />
      </Screen>
    );
  }

  // Pilha, não Slot: o post, o perfil de outra pessoa e o editar perfil ficam por cima das
