            fim: "2026-11-03",
            digitado: true,
          },
        }),
      ],
      proximo: null,
    }),
  );
  aprovacao = jest.fn(
    async (_pedido: Request) => new Response(null, { status: 204 }),
  );
  reprovacao = jest.fn(
    async (_pedido: Request) => new Response(null, { status: 204 }),
