  nomeDeExibicao: "Coordenação UniMax",
  foto: null,
};

function contestacao(
  id: string,
  nome: string,
  extra: Partial<Record<string, unknown>> = {},
) {
  return {
    id,
    premioId: `premio-${id}`,
    postId: null,
    aluno: {
      id: `aluno-${id}`,
      nomeDeExibicao: nome,
      arroba: `@${nome.toLowerCase()}-CC`,
      curso: "CC",
      semestre: 3,
      foto: null,
    },
    item: "P03",
    nomeDoItem: "Palestra ou workshop opcional",
    tier: "bronze",
    pontos: 20,
    evento: {
      id: "e1",
      nome: "Workshop de carreira e currículo",
      inicio: "2026-09-09",
      fim: "2026-09-09",
      digitado: false,
    },
    materia: null,
    foto: null,
    legenda: null,
    motivo: "O nome não está na lista de presença.",
    contestadaPor: "@renataAlbuquerque-PROF",
    contestadaEm: new Date().toISOString(),
    aprovadoEm: new Date().toISOString(),
    passouDoPrazo: false,
    ...extra,
  };
}

