    const caminho = new URL(pedido.url).pathname;
    if (caminho === "/api/v1/eu") return json(200, COORDENACAO);
    if (caminho === "/api/v1/cursos")
      return json(200, [
        { id: ADM, sigla: "ADM", nome: "Administração", duracaoEmSemestres: 8 },
