        erro={purgar.isError ? falhaParaTela(purgar.error).mensagem : null}
        onConfirmar={() =>
          escolhido &&
          purgar.mutate(
            { lote: escolhido.lote, confirmacao: confirmacao.trim() },
            { onSuccess: fechar },
          )
        }
        onFechar={fechar}
      >
        <TextField
          label="Nome do lote"
          value={confirmacao}
          onChangeText={setConfirmacao}
          placeholder={escolhido?.lote}
          autoCapitalize="none"
          autoCorrect={false}
        />
      </FolhaDeAto>
    </ScrollView>
  );
